package dev.linqfy.bigCasares.modules.alexscaves.core.worldgen;

/**
 * Deterministic 2D value noise in [-1, 1]. Used to warp biome borders the way
 * the mod's Perlin offsets do; exact vanilla noise parity is not needed because
 * the surrounding terrain is generated by Paper anyway.
 */
public final class SeededValueNoise {
    private final long seed;

    public SeededValueNoise(long seed) {
        this.seed = seed;
    }

    public double sample(double x, double z) {
        long x0 = (long) Math.floor(x);
        long z0 = (long) Math.floor(z);
        double fx = smooth(x - x0);
        double fz = smooth(z - z0);
        double a = lattice(x0, z0);
        double b = lattice(x0 + 1, z0);
        double c = lattice(x0, z0 + 1);
        double d = lattice(x0 + 1, z0 + 1);
        double top = a + (b - a) * fx;
        double bottom = c + (d - c) * fx;
        return top + (bottom - top) * fz;
    }

    private double lattice(long x, long z) {
        long hash = SeededHash.hash(seed, x, z);
        // 53 random bits mapped to [-1, 1).
        return ((hash >>> 11) * 0x1.0p-53) * 2.0 - 1.0;
    }

    private static double smooth(double t) {
        return t * t * (3.0 - 2.0 * t);
    }
}
